    'cdr_reports.help_body2' => 'Всеки ред е един разговор: под <b>Обаждащ се</b> е транкът, по който е дошъл, под <b>Набран</b> — маршрутът и, ако разговорът е излязъл от PBX, транкът и изпратеният номер; <b>Отговорен от</b> е вътрешният номер, който е приел разговора. <b>Посока</b>: Входящ, Изходящ, Вътрешен или Транк към транк (влязъл по един транк и излязъл по друг, без да е отговорил вътрешен номер на AiPBX). Разгънете ред, за да видите пътя на прехвърлените разговори. Филтрирайте по дата, състояние, вътрешен номер, устройство, посока и транк; слушайте или изтегляйте записите.',
