    'asterisk_settings.rtp_section_title' => 'RTP (медийни) настройки',
    'asterisk_settings.rtp_help_body' => 'Определя кой диапазон от портове пренася аудиото (RTP) и дали Asterisk отхвърля аудио, пристигащо от неочакван източник. Този файл (<code>/etc/asterisk/rtp.conf</code>) вече се генерира от панела; ръчните промени на сървъра се губят при следващото „Прилагане“.',
    'asterisk_settings.field_rtp_start' => 'Начален RTP порт',
    'asterisk_settings.rtp_start_help' => 'Начало на диапазона от портове, запазени за аудио потоци. Всеки едновременен разговор използва портове от този диапазон.',
    'asterisk_settings.field_rtp_end' => 'Краен RTP порт',
    'asterisk_settings.rtp_end_help' => 'Край на диапазона. coturn (TURN релей) използва 13479-14999 — припокриването нарушава WebRTC аудиото и се отхвърля при запазване.',
    'asterisk_settings.field_rtp_strict' => 'Стриктен RTP (strictrtp)',
    'asterisk_settings.rtp_strict_help' => 'Когато е включено, Asterisk безшумно отхвърля аудио, пристигащо от източник, различен от научения отдалечен адрес/порт (защита от атаки). Ако отсрещната PBX изпраща медия от неочакван порт, това води до тиха повреда „няма звук“ без следа в журналите — може временно да се изключи за диагностика.',
    'asterisk_settings.rtp_strict_yes' => 'Включено (препоръчително)',
