    'asterisk_settings.rtp_restart_warning' => 'Настройката Стриктен RTP влиза в сила с „Прилагане“. Промяната на ДИАПАЗОНА ОТ ПОРТОВЕ обаче изисква пълно рестартиране на Asterisk — пулът от портове се заделя еднократно при зареждане на модула.',
    'asterisk_settings.udptl_section_title' => 'T.38 UDPTL (факс медия) настройки',
