    'trunks.connection_mode_register' => 'Входяща регистрация (отсрещната страна се регистрира при нас)',
    'trunks.connection_mode_help' => 'На база IP: отсрещната страна се идентифицира по своя IP адрес и нейният контакт се поддържа статичен — препоръчителният режим за отсрещна страна с фиксиран IP в същата мрежа. Входяща регистрация: отсрещната страна ни изпраща SIP REGISTER и адресът ѝ се научава от тази регистрация. Този режим изисква потребителско име и парола; отсрещната страна удостоверява с тях както регистрацията, така и разговорите си.',
    'trunks.connection_mode_warning' => 'Превключването към режим на регистрация премахва статичния контакт: НЕ можем да се обаждаме към този транк, ДОКАТО отсрещната страна не се регистрира при нас. Направете тази промяна синхронно с настройката за регистрация от отсрещната страна.',
