    'sound_packs.tab' => 'Звукови пакети на Asterisk',
    'sound_packs.title' => 'Официални звукови пакети на Asterisk',
    'sound_packs.help_title' => 'Звукови пакети на Asterisk',
    'sound_packs.help_body' => 'Изтегля и инсталира официалните системни подкани и музика при задържане на Asterisk от <code>downloads.asterisk.org</code>. Всеки пакет е един език в един формат; Asterisk възпроизвежда формата, съответстващ на кодека на разговора, а в противен случай прекодира (g722 за G.722, ulaw/alaw за операторите).<br>- <strong>Основни:</strong> системни подкани, цифри, гласова поща. <strong>Допълнителни:</strong> допълнителни подкани; първо трябва да бъде инсталиран основният пакет за същия език.<br>- <strong>Музика при задържане (opsound):</strong> инсталира се в <code>/var/lib/asterisk/moh/opsound</code>; за да я възпроизвеждате, създайте MOH клас с име <strong>opsound</strong> в раздела Музика при задържане.<br>- <strong>Türkçe (AiPBX):</strong> собствените турски подкани на AiPBX (GitHub release, проверени с SHA256); езикът по подразбиране е турски, така че премахването им заглушава системните подкани. Премахването изтрива само файловете, инсталирани от пакета.',
