    'system_update.help_body' => 'Обновяването първо архивира базата данни, настройките и конфигурацията на Asterisk, след това инсталира новата версия и проверява дали всичко работи. Ако нещо се провали, системата автоматично се връща към предишната версия. По време на обновяването Asterisk се рестартира: текущите разговори прекъсват, затова обновяването не започва, докато има активни разговори. Може да се стартира и на сървъра: <code>sudo aipbx-update</code>',
