    'certificates.header_title' => 'TLS сертификат',
    'certificates.help_title' => 'Ръководство за сертификати',
    'certificates.help_body' => 'Порталът (HTTPS), WebRTC TURNS и SIP-TLS/WSS използват общ сертификат; промените тук се прилагат едновременно към Apache, coturn и Asterisk. <b>Let\'s Encrypt</b> е безплатен и се подновява автоматично; домейнът трябва да сочи към този сървър, а порт 80 трябва да е достъпен от интернет. Ако Вашата организация разполага със сертификат, <b>качете го</b> (PEM или PFX); качените сертификати не се подновяват автоматично, затова качете нов преди изтичането му. При <b>самоподписан</b> сертификат браузърите показват предупреждение и TURNS не работи в браузъри: WebRTC разговорите зад защитни стени може да нямат звук.',
