    'queue_reports.help_title' => 'Ръководство за отчетите на опашките',
    'queue_reports.help_body' => 'Всеки разговор, влязъл в опашка, се отчита веднъж. <b>Отговорени</b>: свързани с агент. <b>Изгубени</b>: обаждащият се е затворил по време на изчакване или времето на опашката е изтекло. <b>Кратко отказване</b>: затворено в рамките на %d секунди; не се включва в нивото на обслужване. <b>Ниво на обслужване</b>: разговорите, отговорени в рамките на целта, спрямо всички разговори без кратките откази. <b>ASA</b>: средно изчакване на отговорените разговори. <b>AHT</b>: средна продължителност на разговора. <b>Процент на поемане</b> (агент): колко често агентът е отговорил, когато опашката му е звъняла. <b>Обратно обаждане</b>: изгубеният разговор се счита за решен, ако по-късно номерът е бил набран от вътрешен номер или се е обадил отново и е получил отговор. Данните идват от журнала на опашките на Asterisk; отчетът може да се изтегли като PDF или Excel.',
