    'ai_tts.help_title' => 'Ръководство за облачен TTS',
    'ai_tts.help_body' => 'Превръща текст в естествена реч чрез облачни услуги (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Прослушайте резултата, изтеглете го като MP3 или го запазете като <b>съобщение</b> с едно щракване: той се конвертира във формата на Asterisk (8 kHz WAV) и се добавя към Звуци &amp; съобщения за IVR, входящи маршрути и времеви условия (влиза в сила след Прилагане). <b>Тези услуги са платени</b> и таксуват на символ; всеки синтез се пази в историята с броя символи. Ключовете за достъп се взимат от конзолата на всеки доставчик, съхраняват се криптирани и никога повече не се показват на страницата.',
