    'push.help_layer0' => '<strong>Слой 0 (без зависимости - по подразбиране):</strong> постоянна WSS връзка, съвместима с Android 15 услуга на преден план <code>specialUse</code> и устойчив на Doze <code>AlarmManager</code> надзорник, който я възстановява. Не е нужна външна услуга; разговорите пристигат дори когато устройството е неактивно или екранът е изключен.',
