    'storage.help_title' => 'Къде се пазят файловете от чата',
    'storage.help_body' => '<p>Прикачените файлове в чата, техните миниатюри и снимките на групите по подразбиране се съхраняват на диска на сървъра (<code>/var/lib/aipbx/chat_files</code>). С S3-съвместимо хранилище (AWS S3, MinIO, Wasabi, Backblaze B2, Cloudflare R2 …) те отиват в bucket и големите файлове не натоварват централата.</p><p>Изтеглянията продължават да минават през услугата за чат, така че само участниците в даден чат могат да отварят файловете му; bucket-ът може да остане частен. Файловете, записани преди превключването, продължават да се предоставят от диска, докато не ги преместите. Настройките на bucket-а се проверяват, преди да бъдат записани.</p><p>Записите на разговори, гласовата поща и факсовете остават на локалния диск.</p>',
