    'netsvc.help_title' => 'Мрежови услуги',
    'netsvc.help_body' => 'Настолните телефони сами намират сървъра за провизиране, когато DHCP сървърът раздава адреса му (option 66). DHCP и TFTP се включват поотделно. При изключен <strong>DHCP сървър</strong> остава вашият собствен DHCP сървър: задайте там опциите, изброени по-долу. При включен AiPBX раздава адреси на един интерфейс или VLAN. <strong>TFTP сървърът</strong> предоставя качените от вас boot файлове и фърмуер. Конфигурацията на всеки телефон (със SIP паролата) винаги се предоставя през HTTPS, никога през TFTP.',
